<script setup lang="ts">
import {ref, onMounted, nextTick} from 'vue'
import {splitTarget, joinTarget} from './proxy-address'
import {readAPIResponse} from './api-response'
type Route={id:string;name?:string;domain:string;port:number;scheme:string;upstream:string;certificate_id:string;enabled:boolean}
type Cert={id:string;domains:string[];mode:string;email:string;provider:string;token_env:string;staging:boolean}
type DDNS={id:string;provider:string;zone_id:string;record_id:string;name:string;type:string;ip:string;token_env:string;interval_seconds:number;enabled:boolean}
type Config={revision:number;routes:Route[];certificates:Cert[];ddns:DDNS[]}
const token=ref(''),logged=ref(false),busy=ref(false),message=ref(''),tab=ref('routes'),status=ref<{proxy?:{running:boolean;modules?:string[]};ddns?:Record<string,{ok:boolean;message:string;ip:string;at:string}>}>({})
const config=ref<Config>({revision:0,routes:[],certificates:[],ddns:[]})
const route=ref<Route>(newRoute()),cert=ref<Cert>(newCert()),dns=ref<DDNS>(newDNS()),domains=ref(''),editing=ref(false)
const target=ref(splitTarget(route.value.upstream))
const editor=ref<HTMLDialogElement>(), viewer=ref<HTMLDialogElement>(), deletion=ref<HTMLDialogElement>()
const copyMessage=ref('')
const modalError=ref(''), viewError=ref(''), viewBusy=ref(false), viewTab=ref<'draft'|'applied'>('draft')
const caddyView=ref<{draft:unknown;applied:unknown}>({draft:null,applied:null})
const pendingDelete=ref<{kind:'routes'|'certificates'|'ddns';key:string;name:string}>()
function closeEditor(){if(!busy.value)editor.value?.close()}
async function openEditor(){modalError.value=''; await nextTick(); editor.value?.showModal();editor.value?.querySelector<HTMLElement>('select,input')?.focus()}
function add(){editing.value=false;route.value=newRoute();target.value=splitTarget(route.value.upstream);cert.value=newCert();dns.value=newDNS();domains.value='';openEditor()}
function askDelete(kind:'routes'|'certificates'|'ddns',key:string,name:string){pendingDelete.value={kind,key,name};modalError.value='';deletion.value?.showModal()}
async function showCaddy(){viewer.value?.showModal();await loadCaddy()}
async function loadCaddy(){copyMessage.value='';viewBusy.value=true;viewError.value='';try{caddyView.value=await api('/proxy/config')}catch(e){caddyView.value={draft:null,applied:null};viewError.value=e instanceof Error?e.message:String(e)}finally{viewBusy.value=false}}
async function copyConfig(){try{await navigator.clipboard.writeText(JSON.stringify(caddyView.value[viewTab.value],null,2));copyMessage.value='配置已复制'}catch{viewError.value='浏览器不支持复制，请选择配置文本手动复制。'}}
function logout(){logged.value=false;token.value='';sessionStorage.removeItem('netlite-token')}
function id(){return Array.from(crypto.getRandomValues(new Uint8Array(8)),b=>b.toString(16).padStart(2,'0')).join('')}
function newRoute():Route{return {id:id(),name:'',domain:'',port:18080,scheme:'http',upstream:'http://127.0.0.1:8080',certificate_id:'',enabled:true}}
function newCert():Cert{return {id:id(),domains:[],mode:'internal',email:'',provider:'cloudflare',token_env:'NETLITE_CF_TOKEN',staging:true}}
function newDNS():DDNS{return {id:id(),provider:'cloudflare',zone_id:'',record_id:'',name:'',type:'A',ip:'',token_env:'NETLITE_CF_TOKEN',interval_seconds:300,enabled:false}}
async function api<T>(url:string,method='GET',body?:unknown):Promise<T>{const r=await fetch('/api'+url,{method,headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});return readAPIResponse<T>(r,url)}
async function action(fn:()=>Promise<void>){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refresh(){status.value=await api('/status')}
async function login(){await action(async()=>{config.value=await api('/config');logged.value=true;sessionStorage.setItem('netlite-token',token.value);await refresh()})}
async function save(){config.value=await api('/config','PUT',config.value);message.value='配置已保存。反代与证书需点击「应用到代理」生效；已启用 DDNS 会自动运行。'}
function editRoute(x:Route){route.value={...x};target.value=splitTarget(x.upstream);editing.value=true;openEditor()}
function editCert(x:Cert){cert.value={...x,domains:[...x.domains]};domains.value=x.domains.join(', ');editing.value=true;openEditor()}
function editDNS(x:DDNS){dns.value={...x};editing.value=true;openEditor()}
function upsert<T extends {id:string}>(list:T[],x:T){const i=list.findIndex(a=>a.id===x.id);if(i<0)list.push(x);else list[i]=x}
async function submitRoute(){modalError.value='';try{route.value.upstream=joinTarget(target.value)}catch(e){modalError.value=e instanceof Error?e.message:String(e);return}await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.routes,{...route.value});try{await save();route.value=newRoute();editing.value=false;editor.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
async function submitCert(){modalError.value='';await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.certificates,{...cert.value,domains:domains.value.split(/[,\s]+/).filter(Boolean)});try{await save();cert.value=newCert();domains.value='';editing.value=false;editor.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
async function submitDNS(){modalError.value='';await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.ddns,{...dns.value});try{await save();dns.value=newDNS();editing.value=false;editor.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
async function remove(kind:'routes'|'certificates'|'ddns',key:string){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));config.value[kind]=config.value[kind].filter(x=>x.id!==key) as Route[]&Cert[]&DDNS[];try{await save();deletion.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
onMounted(()=>{token.value=sessionStorage.getItem('netlite-token')||'';if(token.value)login()})
</script>
<template>
 <main><header><div class="brand"><span class="logo">N</span><div><h1>NetLite</h1><p>让网络管理轻一点</p></div></div><span class="badge">0.1 · 本地管理</span></header>
 <section v-if="!logged" class="login card"><h2>进入管理面板</h2><p>输入应用私有数据目录中 admin-token 文件的管理令牌。</p><form @submit.prevent="login"><label>管理令牌<input v-model="token" type="password" autocomplete="current-password" required></label><button :disabled="busy">登录</button></form></section>
 <template v-else>
 <div class="toolbar"><span :class="['dot',status.proxy?.running?'on':'']"></span><span>Caddy {{status.proxy?.running?'运行中':'未运行'}}</span><span class="muted">配置版本 {{config.revision}}</span><button class="secondary" :disabled="busy" @click="showCaddy">查看 Caddy 配置</button><button class="secondary" :disabled="busy" @click="action(refresh)">刷新状态</button><button class="secondary" :disabled="busy" @click="action(async()=>{await api('/proxy/validate','POST');message='配置校验通过'})">校验配置</button><button :disabled="busy" @click="action(async()=>{const r=await api<{applied_revision:number}>('/proxy/apply','POST');message='已应用版本 '+r.applied_revision+'；证书签发与续期由 Caddy 异步执行';await refresh()})">应用到代理</button></div>
 <nav><button v-for="[key,title] in [['routes','反向代理'],['certificates','HTTPS 证书'],['ddns','动态 DNS']]" :class="{active:tab===key}" @click="tab=key!;editing=false">{{title}}</button><button class="logout" @click="logout">退出</button></nav>
 <div v-if="tab==='routes'" class="content-list"><section class="card"><div class="section-head"><h2>代理规则</h2><button :disabled="busy" @click="add">＋ 添加代理</button></div><p class="muted">按域名和端口访问内网服务，支持 WebSocket。</p><p v-if="!config.routes.length" class="empty">还没有规则，点击「添加代理」开始。</p><div v-if="config.routes.length" class="proxy-table-wrap" tabindex="0" aria-label="代理规则表格，窄屏可左右滚动"><table class="proxy-table"><colgroup><col class="name-col"><col class="protocol-col"><col class="address-col"><col class="port-col"><col class="protocol-col"><col class="address-col"><col class="port-col"><col class="status-col"><col class="actions-col"></colgroup><thead><tr class="group-heading"><th scope="col" rowspan="2">名称 / 备注</th><th scope="colgroup" colspan="3">访问端</th><th scope="colgroup" colspan="3" class="target-start">目标端</th><th scope="col" rowspan="2">状态</th><th scope="col" rowspan="2" class="actions-heading">操作</th></tr><tr><th scope="col">协议</th><th scope="col">域名</th><th scope="col">端口</th><th scope="col" class="target-start">协议</th><th scope="col">地址</th><th scope="col">端口</th></tr></thead><tbody><tr v-for="r in config.routes" :key="r.id"><td><span :class="['route-name',{unnamed:!r.name}]">{{r.name || '—'}}</span></td><td><span :class="['protocol-badge',r.scheme]">{{r.scheme.toUpperCase()}}</span></td><td><strong class="domain-name">{{r.domain}}</strong></td><td><span class="port-number">{{r.port}}</span></td><td class="target-start"><span :class="['protocol-badge',splitTarget(r.upstream).scheme]">{{splitTarget(r.upstream).scheme.toUpperCase()}}</span></td><td><span class="target-address">{{splitTarget(r.upstream).address}}</span></td><td><span class="port-number target-port">{{splitTarget(r.upstream).port}}</span></td><td><span :class="['route-status',r.enabled?'enabled':'disabled']">{{r.enabled?'启用':'停用'}}</span></td><td><div class="small-actions"><button class="secondary" :disabled="busy" :aria-label="'编辑 '+r.domain+':'+r.port" @click="editRoute(r)">编辑</button><button class="danger" :disabled="busy" :aria-label="'删除 '+r.domain+':'+r.port" @click="askDelete('routes',r.id,(r.name?r.name+' · ':'')+r.domain+':'+r.port)">删除</button></div></td></tr></tbody></table></div></section>
 </div>
 <div v-if="tab==='certificates'" class="content-list"><section class="card"><div class="section-head"><h2>证书策略</h2><button :disabled="busy" @click="add">＋ 添加证书</button></div><p class="muted">Caddy 自动签发和续期。DNS-01 泛域名需要对应插件和凭据。</p><p v-if="!config.certificates.length" class="empty">暂无内容，点击上方添加按钮开始。</p><article v-for="c in config.certificates" :key="c.id"><div><strong>{{c.domains.join(', ')}}</strong><p>{{c.mode}} {{c.mode!=='internal'?(c.staging?'· 测试 CA':'· 正式 CA'):''}}</p></div><div class="small-actions"><button class="secondary" @click="editCert(c)">编辑</button><button class="danger" :disabled="busy" @click="askDelete('certificates',c.id,c.domains.join(', '))">删除</button></div></article><aside>应用成功仅表示配置生效。签发失败和续期信息见应用数据目录 caddy.log。内部证书需客户端自行信任。</aside></section>
 </div>
 <div v-if="tab==='ddns'" class="content-list"><section class="card"><div class="section-head"><h2>动态 DNS</h2><button :disabled="busy" @click="add">＋ 添加 DDNS</button></div><p class="muted">Cloudflare A / AAAA 记录定时同步，保留现有 TTL 和代理开关。</p><p v-if="!config.ddns.length" class="empty">暂无内容，点击上方添加按钮开始。</p><article v-for="d in config.ddns" :key="d.id"><div><strong>{{d.name}} · {{d.type}}</strong><p>{{d.enabled?'启用':'停用'}} · 每 {{d.interval_seconds}} 秒</p><p v-if="status.ddns?.[d.id]">{{status.ddns[d.id]?.ok?'✓':'!'}} {{status.ddns[d.id]?.message}} {{status.ddns[d.id]?.ip}}</p></div><div class="small-actions"><button class="secondary" @click="editDNS(d)">编辑</button><button class="secondary" :disabled="busy||!d.enabled" @click="action(async()=>{await api('/ddns/'+d.id+'/run','POST');await refresh();message='DDNS 已执行，请查看结果'})">立即同步</button><button class="danger" :disabled="busy" @click="askDelete('ddns',d.id,d.name)">删除</button></div></article></section>
 </div>

 <dialog ref="editor" class="editor-dialog" aria-labelledby="editor-title" @cancel="busy && $event.preventDefault()"><section v-if="tab==='routes'"><div class="dialog-head"><h2 id="editor-title">{{editing?'编辑':'添加'}}代理</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="closeEditor">×</button></div><form @submit.prevent="submitRoute"><label>名称 / 备注（选填）<input v-model="route.name" placeholder="例如：家庭相册、下载工具"></label><fieldset class="endpoint-fields"><legend>访问端</legend><div class="endpoint-row"><label>访问协议<select v-model="route.scheme"><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label>访问域名<input v-model="route.domain" placeholder="app.example.com" required></label><label>访问端口<input v-model.number="route.port" type="number" min="1024" max="65535" required></label></div></fieldset><fieldset class="endpoint-fields"><legend>目标端</legend><div class="endpoint-row"><label>目标协议<select v-model="target.scheme"><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label>目标地址<input v-model="target.address" placeholder="192.168.1.10 或 service.local" required></label><label>目标端口<input v-model.number="target.port" type="number" min="1" max="65535" required></label></div><p class="muted">目标地址填写实际提供服务的 IP 或域名。127.0.0.1 表示运行 NetLite 的这台设备。</p></fieldset><label v-if="route.scheme==='https'">证书策略<select v-model="route.certificate_id" required><option value="">请选择覆盖该域名的证书</option><option v-for="c in config.certificates" :value="c.id">{{c.domains.join(', ')}}</option></select></label><label class="check"><input v-model="route.enabled" type="checkbox">启用规则</label><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="closeEditor">取消</button><button :disabled="busy">保存规则</button></div></form></section><section v-if="tab==='certificates'"><div class="dialog-head"><h2 id="editor-title">{{editing?'编辑':'添加'}}证书策略</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="closeEditor">×</button></div><form @submit.prevent="submitCert"><label>域名（逗号分隔）<input v-model="domains" placeholder="*.example.com, example.com" required></label><label>签发方式<select v-model="cert.mode"><option value="internal">内部 CA（本地测试）</option><option value="acme">ACME（HTTP / TLS-ALPN）</option><option value="dns">DNS-01（Cloudflare 插件）</option></select></label><label v-if="cert.mode!=='internal'">联系邮箱<input v-model="cert.email" type="email"></label><label v-if="cert.mode==='dns'">令牌环境变量名<input v-model="cert.token_env" required></label><label v-if="cert.mode!=='internal'" class="check"><input v-model="cert.staging" type="checkbox">使用 Let's Encrypt 测试 CA</label><p class="muted">ACME 端口验证需公网 80/443 映射到应用端口。DNS-01 无需开放验证端口。</p><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="closeEditor">取消</button><button :disabled="busy">保存策略</button></div></form></section><section v-if="tab==='ddns'"><div class="dialog-head"><h2 id="editor-title">{{editing?'编辑':'添加'}} DDNS</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="closeEditor">×</button></div><form @submit.prevent="submitDNS"><label>记录域名<input v-model="dns.name" required></label><div class="fields"><label>记录类型<select v-model="dns.type"><option>A</option><option>AAAA</option></select></label><label>更新间隔（秒）<input v-model.number="dns.interval_seconds" type="number" min="60" max="86400" required></label></div><label>Zone ID<input v-model="dns.zone_id" required></label><label>Record ID<input v-model="dns.record_id" required></label><label>令牌环境变量名<input v-model="dns.token_env" required></label><label>指定 IP（留空自动发现）<input v-model="dns.ip" placeholder="自动发现 IPv4 / IPv6 公网地址"></label><label class="check"><input v-model="dns.enabled" type="checkbox">保存后启用自动更新</label><p class="muted">凭据在启动环境中配置；界面不存储 API 密钥。</p><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="closeEditor">取消</button><button :disabled="busy">保存 DDNS</button></div></form></section></dialog>
 <dialog ref="deletion" class="delete-dialog" aria-labelledby="delete-title" @cancel="busy && $event.preventDefault()"><div class="dialog-head"><h2 id="delete-title">确认删除</h2></div><p>确定删除「{{pendingDelete?.name}}」？</p><p class="muted">{{pendingDelete?.kind==='ddns'?'删除后将停止该记录的自动更新。':'删除后需应用到代理，反代与证书的变更才会生效。'}}</p><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="deletion?.close()">取消</button><button class="danger" :disabled="busy" @click="pendingDelete && remove(pendingDelete.kind,pendingDelete.key)">确认删除</button></div></dialog>
 <dialog ref="viewer" class="config-dialog" aria-labelledby="config-title"><div class="dialog-head"><h2 id="config-title">Caddy 配置</h2><button class="icon-button" aria-label="关闭配置" @click="viewer?.close()">×</button></div><p class="muted">草稿由当前保存的规则生成；已应用配置为最近成功应用后保存的配置。凭据已隐藏。</p><div class="config-toolbar"><button :class="['secondary',{selected:viewTab==='draft'}]" @click="viewTab='draft'">配置草稿</button><button :class="['secondary',{selected:viewTab==='applied'}]" @click="viewTab='applied'">已应用配置</button><button class="secondary" :disabled="viewBusy" @click="loadCaddy">刷新</button><button class="secondary" :disabled="viewBusy||!caddyView[viewTab]" @click="copyConfig">复制配置</button></div><p v-if="copyMessage" class="muted" role="status">{{copyMessage}}</p><p v-if="viewError" class="form-error" role="alert">{{viewError}}</p><p v-if="viewBusy" class="empty">正在加载配置…</p><pre v-else-if="caddyView[viewTab]" tabindex="0">{{JSON.stringify(caddyView[viewTab],null,2)}}</pre><p v-else-if="!viewError" class="empty">{{viewTab==='applied'?'尚未应用过配置。':'暂无配置草稿。'}}</p><div class="dialog-actions"><button @click="viewer?.close()">关闭</button></div></dialog>
 </template><div v-if="message" class="message" role="status">{{message}}</div><footer>独立代理进程 · SQLite 配置 · 不接管系统 Web 服务</footer></main>
</template>
